import{_ as r,a0 as a,w as l,s as i,ao as m,I as s,x as e,a1 as n,A as p}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"如何在终端下截取一个完整长度的网页截图 | LCTT x X-CMD","titleTemplate":false,"description":"如何在终端下截取一个完整长度的网页截图 | LCTT (201406) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在终端下截取一个完整长度的网页截图 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在终端下截取一个完整长度的网页截图 | LCTT (201406) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201406/How to take full length screenshots of websites via terminal","title":"如何在终端下截取一个完整长度的网页截图","tag":"201406","desc":""},"relativePath":"201406/How to take full length screenshots of websites via terminal.md","filePath":"[post].md"}'),d={name:"201406/How to take full length screenshots of websites via terminal.md"};function u(g,t,w,h,f,T){const o=a("Link");return l(),i("div",null,[t[11]||(t[11]=m(`<h1 id="如何在终端下截取一个完整长度的网页截图" tabindex="-1">如何在终端下截取一个完整长度的网页截图 <a class="header-anchor" href="#如何在终端下截取一个完整长度的网页截图" aria-label="Permalink to “如何在终端下截取一个完整长度的网页截图”">​</a></h1><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2014/04/Screenshot-790x526.png" alt=""></p><p>与其记笔记或是把看到的内容发送给其他人，我们更经常通过截屏来帮助我们记忆。 但是通常情况下，如果一个网页超出了屏幕高度，我们就得用多张截图去截取其全部内容。</p><p>对于 Linux，你将会有一个更好的解决方案：使用一个 GNOME 的应用来截取某个链接的整个页面。 这个应用叫做 <strong>gnome-web-photo</strong>，这篇文章将介绍如何安装和使用它。</p><p>在 Ubuntu 和 Debian 的分支下：</p><pre><code>$ sudo apt-get install gnome-web-photo
</code></pre><p>在 Fedora 下：</p><pre><code>$ sudo yum install gnome-web-photo
</code></pre><p>但是对于 CentOS 和其他 RedHat 分支的用户，请注意 <code>gnome-web-photo</code> 依赖 GTK+ 3.0 这个软件包。 也就是说 <code>gnome-web-photo</code> 是和 <strong>CentOS/RHEL 6 自带的 GNOME 2 不相兼容的</strong>。</p><p>要为一个网页截图：</p><pre><code>$ gnome-web-photo -t 0 --mode=photo http://www.unixmen.com output.png
</code></pre><p>上面这条命令将为 Unixmen 的主页截取一个完整长度的截图，并保存在当前工作目录下。</p><p>输出样例：</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2014/04/output2.png" alt=""></p><p><strong>-t</strong> 这个参数可以设置生成截图的超时时间。<strong>-t 0</strong> 则表示禁用超时参数。</p><p><strong>通过</strong> gnome-web-photo，你可以用下面的命令为一个网页生成一个缩略图：（默认大小是 <strong>256×256</strong>，但是可以通过 “<strong>-s</strong>” 来指定缩略图的大小）</p><pre><code>$ gnome-web-photo -t 0 -s 128 --mode=thumbnail http://www.unixmen.com output.png
</code></pre><p>输出样例：</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2014/04/output.png" alt=""></p><p>如果你想将网页截取成一个可供打印的多页 PDF 文档，你可以输入下面的命令：</p><pre><code>$ gnome-web-photo -t 0 --mode=print http://www.unixmen.com output.pdf
</code></pre><p>注意这个应用并不支持 <strong>.jpg</strong> 格式。</p><p>这个应用应该对各类用户都有所帮助。我经常对网页进行缩略图和完整长度的截图，希望对你也有所帮助。</p><hr>`,24)),s("p",null,[t[1]||(t[1]=e("via: ",-1)),n(o,{href:"http://www.unixmen.com/take-full-length-screenshots-websites-via-terminal/"},{default:p(()=>[...t[0]||(t[0]=[e("http://www.unixmen.com/take-full-length-screenshots-websites-via-terminal/",-1)])]),_:1})]),s("p",null,[t[4]||(t[4]=e("译者：",-1)),n(o,{href:"https://github.com/vizv"},{default:p(()=>[...t[2]||(t[2]=[e("VizV",-1)])]),_:1}),t[5]||(t[5]=e(" 校对：",-1)),n(o,{href:"https://github.com/carolinewuyan"},{default:p(()=>[...t[3]||(t[3]=[e("Caroline",-1)])]),_:1})]),s("p",null,[t[8]||(t[8]=e("本文由 ",-1)),n(o,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...t[6]||(t[6]=[e("LCTT",-1)])]),_:1}),t[9]||(t[9]=e(" 原创翻译，",-1)),n(o,{href:"http://linux.cn/"},{default:p(()=>[...t[7]||(t[7]=[e("Linux中国",-1)])]),_:1}),t[10]||(t[10]=e(" 荣誉推出",-1))])])}const C=r(d,[["render",u]]);export{x as __pageData,C as default};
